import * as M from './model.js';
import * as C from './curriculum.js';
import * as CP from './class-curriculum.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,data='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
const options=(values,current)=>values.map(([value,label])=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`).join('');
export function view(s,tab='plan'){const d=CP.data(s),p=d.draft,active=d.active,late=!active&&s.day>CP.deadline(s),tabs=`<nav class="curriculum-tabs" aria-label="학급교육과정 화면">${[['plan','운영 계획'],['progress','시수·보완'],['assessment','평가 점검']].map(([id,title])=>btn(title,'curriculum-tab',`data-id="${id}" aria-pressed="${id===tab}"`,id===tab?'primary':'')).join('')}</nav>`;
 let body=`<div class="curriculum-status ${late?'late':''}"><span><b>3월 안에 학급교육과정 수립</b><small>마지막 3월 등교일: ${M.dateLabel({day:CP.deadline(s)})}</small></span><strong>${active?active.number+'차 확정':late?'기한 후 보완 필요':'작성 중'}</strong></div>`+tabs;
 if(tab==='plan'){body+=`<form id="class-curriculum-form" data-class-curriculum><div class="form-grid"><div class="form-field layout-full"><label for="curriculum-goal">우리 반 교육 목표</label><textarea id="curriculum-goal" maxlength="300" rows="2" placeholder="예: 서로의 설명을 끝까지 듣고 배운 것을 자기 말로 표현하는 학급">${esc(p.goal)}</textarea></div><div class="form-field"><label for="curriculum-focus">학급 중점</label><select id="curriculum-focus">${options(Object.entries(CP.FOCUS),p.focus)}</select></div><div class="form-field layout-full"><label for="curriculum-support">학생 특성과 지원 방법</label><textarea id="curriculum-support" maxlength="500" rows="3" placeholder="관찰한 특성과 참여를 도울 방법을 적어 주세요.">${esc(p.support)}</textarea></div></div><h4 class="section-label">교과·창체 운영</h4><div class="curriculum-subjects">${p.rows.map((r,i)=>`<details class="curriculum-subject" data-curriculum-subject="${esc(r.subject)}"><summary><b>${r.subject}</b><span>주 ${s.schedule.flat().filter(x=>x.subject===r.subject).length}차시 · ${esc(r.goal)}</span></summary><div class="form-grid"><div class="form-field layout-full"><label for="cp-goal-${i}">핵심 목표</label><input id="cp-goal-${i}" data-field="goal" maxlength="300" value="${esc(r.goal)}"></div><div class="form-field"><label for="cp-method-${i}">주요 수업 방법</label><select id="cp-method-${i}" data-field="method">${options(C.methods(r.subject,true).map(m=>[m.id,m.name]),r.method)}</select></div><div class="form-field"><label for="cp-room-${i}">활용할 공간</label><select id="cp-room-${i}" data-field="room">${options(C.subjectRooms(r.subject).map(id=>[id,M.ROOMS[id].name]),r.room)}</select></div><div class="form-field"><label for="cp-evidence-${i}">확인할 학습 증거</label><select id="cp-evidence-${i}" data-field="evidence">${options(CP.EVIDENCE.map(x=>[x,x]),r.evidence)}</select></div><div class="form-field"><label for="cp-day-${i}">평가 점검일</label><select id="cp-day-${i}" data-field="assessDay">${options(Array.from({length:M.demoDays(s)},(_,day)=>[day,M.dateLabel({day})]),r.assessDay)}</select></div><div class="form-field layout-full"><label for="cp-materials-${i}">준비물 계획</label><input id="cp-materials-${i}" data-field="materials" maxlength="300" value="${esc(r.materials)}"></div></div></details>`).join('')}</div><h4 class="section-label">창의적 체험활동</h4><div class="form-grid">${p.creative.map((r,i)=>`<div class="form-field layout-full"><label for="cp-creative-${i}">${r.area}</label><input id="cp-creative-${i}" data-creative="${r.area}" maxlength="180" value="${esc(r.topic)}"></div>`).join('')}</div></form><div class="notice">학교 기본 시간표를 바탕으로 수업 방법과 활동을 정합니다. 창체의 세 영역은 기존 창체 차시 안에서 운영하며 시수를 중복 합산하지 않습니다. 계획한 공간으로 자동 이동하지는 않습니다.</div><div class="buttons">${btn('초안 저장','curriculum-save')}${btn(active?'변경 계획 확정 · 20분':'계획 확정 · 20분','curriculum-confirm','','primary')}${active?btn('교사 PC 문서로 만들기','curriculum-file'):''}</div>${active?`<details class="curriculum-history"><summary>확정 이력 ${d.revisions.length}건</summary>${d.revisions.map(r=>`<p><b>${r.number}차</b> ${esc(r.date)}${r.late?' · 기한 후 보완':''}<br>${esc(r.plan.goal)}</p>`).join('')}</details>`:''}`;
 }else if(tab==='progress'){const rows=CP.ledger(s);body+=`<p class="intro">${M.demoDays(s)/5}주 데모의 계획과 실제 수업을 비교합니다. 행사로 대체한 수업은 변경 계획에 반영합니다.</p><div class="curriculum-ledger"><table><thead><tr><th>과목</th><th>기본<br>계획</th><th>변경<br>계획</th><th>실시</th><th>지나간<br>미실시</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${r.subject}</th><td>${r.base}</td><td>${r.planned}</td><td>${r.actual}</td><td class="${r.missed.length?'needs-review':''}">${r.missed.length}</td></tr>`).join('')}</tbody></table></div><h4 class="section-label">다음 수업에서 핵심 목표 다시 다루기</h4><div class="choice-list">${rows.filter(r=>r.missed.length).map(r=>`<article class="curriculum-catchup"><div><b>${r.subject}</b><small>지나간 미실시 ${r.missed.length}차시</small></div>${btn('다음 차시와 연결 · 5분','curriculum-catchup',`data-id="${r.subject}"`)}</article>`).join('')||'<p class="empty">지나간 수업 중 미실시 차시가 없습니다.</p>'}</div>${d.catchups.map(c=>`<div class="note-card"><small>${c.subject} · ${M.dateLabel({day:c.source.day})} ${c.source.period}교시 → ${M.dateLabel({day:c.target.day})} ${c.target.period}교시</small><b>${c.status==='done'?'다시 다룬 수업 기록 있음':c.status==='missed'?'예정 차시도 미실시 · 다시 계획 필요':'다음 수업에 반영 예정'}</b><p>${esc(c.goal)}</p></div>`).join('')}<div class="notice">연결한 다음 차시를 실제로 수업해야 반영됩니다. 과거 미실시 차시를 실시로 바꾸거나 한 수업을 두 차시로 계산하지 않습니다. 방과후·늘봄·기초학력지도는 정규 시수에서 제외합니다.</div>`;
 }else{body+=active?`<div class="assessment-plans">${active.plan.rows.filter(r=>r.subject!=='창체').map(r=>{const count=CP.assessmentCount(s,r.subject);return `<article class="assessment-plan"><div><b>${r.subject}</b><small>${M.dateLabel({day:r.assessDay})} · ${r.evidence}</small><p>${esc(r.goal)}</p></div><span>${count}/${s.students.length}명 기록</span>${btn('평가 기록','curriculum-assess',`data-id="${r.subject}"`)}</article>`;}).join('')}</div><div class="notice">입력한 수행평가 근거가 있는 학생만 확인 인원에 포함합니다. 결석·미실시는 완료나 0점으로 처리하지 않습니다. 평가 계획을 세우는 것만으로 성적이 바뀌지 않습니다.</div>`:'<div class="notice">학급교육과정을 확정하면 과목별 평가 계획과 기록한 학생 수를 확인할 수 있습니다.</div>';}
 return {title:'학급교육과정',body};}
